// Two alarms, each throttled.
// UNREACHABLE: no 200, or a 200 whose body is not the health shape. The engine could not
// answer: a paused project, a failed deploy, a Vercel outage. Nothing inside the app can
// report that, so this workflow does.
// STALE: the engine answered and says no mail has reached it. The engine reports that itself
// too, but its report rides the engine's own lambda and receiver. On 2026-10-01 both were
// dead: 41 stale readings, 0 emails, 53 hours of lost intake. So this alarms on stale as well,
// through its own path (the Spartan Alarms webhook, on the Test Email credential).
const r = $input.first().json ?? {};
const status = Number(r.statusCode ?? 0);
const body = r.body ?? r;
const answered = status === 200 && body && typeof body.ok === 'boolean';

// n8n keeps nothing between runs except this. Without the throttle a day-long outage
// sends 96 identical emails and the sender gets filtered.
const s = $getWorkflowStaticData('global');
s.consecutiveFailures = answered ? 0 : (s.consecutiveFailures || 0) + 1;
s.consecutiveStale = (answered && body.stale === true) ? (s.consecutiveStale || 0) + 1 : 0;
const n = s.consecutiveFailures;
const k = s.consecutiveStale;
// Unreachable: the 1st, then every 4th (hourly). Stale: the 1st, then every 8th (2-hourly).
// k > 0 matters: 0 % 8 is 0, and without it every healthy run would alarm.
const unreachable = !answered && (n === 1 || n % 4 === 0);
const stale = k > 0 && (k === 1 || k % 8 === 0);
const alert = unreachable || stale;
const detail = String(r.error?.message ?? r.message ?? JSON.stringify(body ?? {})).slice(0, 500);

const text = unreachable
  ? 'The Spartan intake health check could not be answered.\n\n' +
    'This is NOT the engine reporting a problem: it is the engine failing to reply at all, which is ' +
    'what a paused project, a failed deploy or a Vercel outage looks like.\n\n' +
    'Endpoint: https://spartan-crew-jobber.vercel.app/api/health/intake\nHTTP status: ' + status +
    '\nConsecutive failures: ' + n + ' (checked every 15 minutes)\n\nDetail: ' + detail +
    '\n\nRepeats on the 1st failure and then every 4th, so this arriving once an hour means it is still down.'
  : 'The engine answered, and says no mail has reached it' +
    (body.minutes_since == null ? ' ever.' : ' for ' + body.minutes_since + ' minutes.') +
    '\n\nCheck the n8n "Bookings intake" executions first: an expired Gmail credential looks exactly ' +
    'like this (2026-10-01, "Gmail account 14").\n\nEngine says: ' + String(body.what ?? '') +
    '\nLast inbound: ' + String(body.last_received_at ?? 'never') +
    '\nConsecutive stale readings: ' + k + ' (checked every 15 minutes)' +
    '\n\nRepeats on the 1st stale reading and then every 8th, so this arriving every 2 hours means intake is still quiet.';

return [{ json: {
  alert, answered, status, consecutive: unreachable ? n : k,
  stale: body?.stale ?? null,
  minutes_since: body?.minutes_since ?? null,
  detail,
  payload: {
    record_id: 'watchdog-' + (unreachable ? 'unreachable' : 'stale'),
    user_name: 'Spartan intake watchdog - ' + (unreachable ? 'the engine did not answer' : 'intake is quiet'),
    user_email: 'watchdog@n8n',
    ts: new Date().toISOString(),
    route: 'n8n/intake-watchdog',
    deploy_sha: null,
    ticket_text: text,
    transcript: '',
  },
} }];
